package com.codepilot1c.core.edt.development;
import static org.junit.Assert.*;
import org.junit.Test;
import java.util.*;
import java.nio.file.*;
import com.google.gson.*;
public class TestDataSetServiceTest {
    static final String HOST=TestDataCreateServiceTest.HOST;static final TestDataLedger.Target TARGET=TestDataCreateServiceTest.TARGET;
    static Map<String,Object> node(String alias,Map<String,Object> fields){return Map.of("alias",alias,"metadata_fqn","Catalog.TestItems","fields",fields);}
    static List<Map<String,Object>> plan(){return List.of(node("Child",Map.of("Owner",Map.of("ref","Parent"))),node("Parent",Map.of("Наименование","Parent")));}
    static class Backend implements TestDataCreateService.Backend {
        int submits;String cleanupOutcome="marked_for_deletion";boolean lose;Map<String,Map<String,Object>> replies=new HashMap<>();
        public TestDataLedger.Target target(String id,boolean running){return TARGET;}
        public Map<String,Object> submit(String id,String key,String code,Map<String,Object> p)throws Exception{submits++;String req=UUID.randomUUID().toString();Map<String,Object> receipt=new HashMap<>();for(String name:List.of("nonce","uuid","expected_version","creation_id","metadata_fqn","cleanup_id","record_id"))if(p.containsKey(name))receipt.put(name,p.get(name));if(p.containsKey("cleanup_id")){receipt.put("protocol","edt-test-data-cleanup-v1");receipt.put("outcome",cleanupOutcome);}else{receipt.put("protocol","edt-test-data-create-v1");receipt.put("created",true);receipt.put("expected_version","version");}replies.put(req,Map.of("request_id",req,"terminal",true,"state","completed","execution",Map.of("success",true,"value",receipt)));if(lose)throw new java.io.IOException("lost");return Map.of("request_id",req);}
        public Map<String,Object> result(String id,String req){return replies.get(req);}
    }
    @Test public void sortsDependenciesAndRejectsCyclesBeforeDispatch(){var plan=TestDataSetService.normalize(plan());assertEquals("Parent",plan.get(0).getAsJsonObject().get("alias").getAsString());assertThrows(IllegalArgumentException.class,()->TestDataSetService.normalize(List.of(node("A",Map.of("Owner",Map.of("ref","A"))))));assertThrows(IllegalArgumentException.class,()->TestDataSetService.normalize(List.of(node("A",Map.of("Owner",Map.of("ref","Missing"))))));assertThrows(IllegalArgumentException.class,()->TestDataSetService.normalize(List.of(node("A",Map.of()),node("A",Map.of()))));}
    @Test public void manualStatusNeverSubmitsNextAndPrimitivesRemainAvailable()throws Exception{try(var f=new TestDataLedgerTest.Fixture()){Backend b=new Backend();var service=new TestDataSetService(f.path.resolve("sets"),f.ledger,b);var set=service.prepare(f.id,TARGET,"one",HOST,plan(),false);String id=set.get("set_id").getAsString();assertEquals(0,b.submits);service.status(id,f.id,TARGET);assertEquals(0,b.submits);service.advance(id,f.id,TARGET);assertEquals(1,b.submits);var first=service.status(id,f.id,TARGET);assertEquals(1,first.get("created_count").getAsInt());service.status(id,f.id,TARGET);assertEquals(1,b.submits);service.advance(id,f.id,TARGET);assertEquals(2,b.submits);var done=service.status(id,f.id,TARGET);assertEquals("completed",done.get("state").getAsString());assertEquals(2,done.getAsJsonObject("aliases").size());}}
    @Test public void automaticModeAndRestartAreDurableAndIdempotent()throws Exception{try(var f=new TestDataLedgerTest.Fixture()){Backend b=new Backend();var service=new TestDataSetService(f.path.resolve("sets"),f.ledger,b);String id=service.prepare(f.id,TARGET,"one",HOST,plan(),true).get("set_id").getAsString();for(int i=0;i<6;i++)new TestDataSetService(f.path.resolve("sets"),f.ledger,b).status(id,f.id,TARGET);assertEquals(2,b.submits);assertEquals("completed",service.prepare(f.id,TARGET,"one",HOST,plan(),true).get("state").getAsString());assertThrows(IllegalArgumentException.class,()->service.prepare(f.id,TARGET,"one",HOST,List.of(node("Different",Map.of())),true));}}
    @Test public void unknownCreationNeverStartsDependents()throws Exception{try(var f=new TestDataLedgerTest.Fixture()){Backend b=new Backend();b.lose=true;var service=new TestDataSetService(f.path.resolve("sets"),f.ledger,b);String id=service.prepare(f.id,TARGET,"one",HOST,plan(),true).get("set_id").getAsString();for(int i=0;i<4;i++)assertEquals("outcome_unknown",service.status(id,f.id,TARGET).get("state").getAsString());assertEquals(1,b.submits);}}
    @Test public void cleanupReversesDependenciesAndRetainedChildProtectsParent()throws Exception{try(var f=new TestDataLedgerTest.Fixture()){Backend b=new Backend();var service=new TestDataSetService(f.path.resolve("sets"),f.ledger,b);String id=service.prepare(f.id,TARGET,"one",HOST,plan(),true).get("set_id").getAsString();for(int i=0;i<5;i++)service.status(id,f.id,TARGET);var preview=service.preview(id,f.id,TARGET);assertEquals("Child",preview.getAsJsonArray("cleanup_order").get(0).getAsString());b.cleanupOutcome="version_changed";service.cleanup(id,f.id,TARGET,preview.get("plan_sha256").getAsString());JsonObject done=null;for(int i=0;i<5;i++)done=service.status(id,f.id,TARGET);assertEquals("completed_with_skips",done.get("state").getAsString());assertEquals("dependent_retained",done.getAsJsonObject("cleanup").getAsJsonObject("Parent").get("outcome").getAsString());assertEquals(3,b.submits);}}
    @Test public void referencesAreInternalAndVersionGuarded()throws Exception{var fields=Map.<String,Object>of("Owner",Map.of("type","reference","metadata_fqn","Catalog.Parent","uuid","12345678-1234-1234-1234-123456789abc","expected_version","v"));assertThrows(IllegalArgumentException.class,()->TestDataCreatePlan.normalize("Catalog.Child",fields));String code=TestDataCreatePlan.code(TestDataCreatePlan.normalizeLinked("Catalog.Child",fields));assertTrue(code.contains("Справочники.Parent.ПолучитьСсылку"));assertTrue(code.contains("expected_version"));assertFalse(code.contains("__"));}
    @Test public void tamperedAliasCannotPointToAnotherOwnedRecord()throws Exception{try(var f=new TestDataLedgerTest.Fixture()){Backend b=new Backend();Path root=f.path.resolve("sets");var service=new TestDataSetService(root,f.ledger,b);String id=service.prepare(f.id,TARGET,"one",HOST,plan(),true).get("set_id").getAsString();for(int i=0;i<5;i++)service.status(id,f.id,TARGET);Path file=root.resolve(id+".json");JsonObject doc=JsonParser.parseString(Files.readString(file)).getAsJsonObject();doc.getAsJsonObject("created").add("Parent",doc.getAsJsonObject("created").get("Child").deepCopy());Files.writeString(file,doc.toString());assertThrows(IllegalArgumentException.class,()->service.advance(id,f.id,TARGET));assertEquals(2,b.submits);}}
    @Test public void staleCleanupPreviewNeverDispatches()throws Exception{try(var f=new TestDataLedgerTest.Fixture()){Backend b=new Backend();var service=new TestDataSetService(f.path.resolve("sets"),f.ledger,b);String id=service.prepare(f.id,TARGET,"one",HOST,plan(),true).get("set_id").getAsString();for(int i=0;i<5;i++)service.status(id,f.id,TARGET);assertThrows(IllegalStateException.class,()->service.cleanup(id,f.id,TARGET,"stale"));assertEquals(2,b.submits);}}
    @Test public void automaticSetCanPauseBeforeNextNode()throws Exception{try(var f=new TestDataLedgerTest.Fixture()){Backend b=new Backend();var service=new TestDataSetService(f.path.resolve("sets"),f.ledger,b);String id=service.prepare(f.id,TARGET,"one",HOST,plan(),true).get("set_id").getAsString();service.pause(id,f.id,TARGET,true);for(int i=0;i<3;i++)service.status(id,f.id,TARGET);assertEquals(1,b.submits);service.pause(id,f.id,TARGET,false);service.status(id,f.id,TARGET);assertEquals(2,b.submits);}}
    @Test public void cleanupPreviewRecoversCreationConfirmedThroughPrimitive()throws Exception{try(var f=new TestDataLedgerTest.Fixture()){Backend backend=new Backend();Path root=f.path.resolve("sets");var service=new TestDataSetService(root,f.ledger,backend);String id=service.prepare(f.id,TARGET,"recover",HOST,plan(),false).get("set_id").getAsString();JsonObject pending=service.advance(id,f.id,TARGET);new TestDataCreateService(f.ledger,backend).status(f.id,TARGET,pending.get("creation_id").getAsString());JsonObject preview=service.preview(id,f.id,TARGET);assertEquals(1,preview.get("created_count").getAsInt());assertEquals("Parent",preview.getAsJsonArray("cleanup_order").get(0).getAsString());assertEquals(1,backend.submits);service.cleanup(id,f.id,TARGET,preview.get("plan_sha256").getAsString());assertEquals(1,backend.submits);}}
    @Test public void previewRecoversMissingSetAckWithoutDispatch()throws Exception{try(var f=new TestDataLedgerTest.Fixture()){Backend backend=new Backend();Path root=f.path.resolve("sets");var service=new TestDataSetService(root,f.ledger,backend);String id=service.prepare(f.id,TARGET,"recover",HOST,plan(),false).get("set_id").getAsString();JsonObject pending=service.advance(id,f.id,TARGET);new TestDataCreateService(f.ledger,backend).status(f.id,TARGET,pending.get("creation_id").getAsString());Path file=root.resolve(id+".json");JsonObject doc=JsonParser.parseString(Files.readString(file)).getAsJsonObject();doc.add("operations",new JsonObject());Files.writeString(file,doc.toString());JsonObject preview=service.preview(id,f.id,TARGET);assertEquals(1,preview.get("created_count").getAsInt());assertEquals(1,backend.submits);}}
    @Test public void primitiveCleanupIsAdoptedWithoutReplayAndProtectsAncestors()throws Exception{try(var f=new TestDataLedgerTest.Fixture()){Backend b=new Backend();var service=new TestDataSetService(f.path.resolve("sets"),f.ledger,b);String id=service.prepare(f.id,TARGET,"one",HOST,plan(),true).get("set_id").getAsString();JsonObject done=null;for(int i=0;i<5;i++)done=service.status(id,f.id,TARGET);String record=done.getAsJsonObject("aliases").getAsJsonObject("Child").get("record_id").getAsString();b.cleanupOutcome="version_changed";var cleanup=new TestDataCleanupService(f.ledger,b);var p=f.ledger.preview(f.id,TARGET,0,1);var op=cleanup.start(f.id,TARGET,"individual-cleanup",HOST,record,p.get("plan_sha256").getAsString());cleanup.status(f.id,TARGET,op.get("cleanup_id").getAsString());var preview=service.preview(id,f.id,TARGET);service.cleanup(id,f.id,TARGET,preview.get("plan_sha256").getAsString());for(int i=0;i<4;i++)done=service.status(id,f.id,TARGET);assertEquals("completed_with_skips",done.get("state").getAsString());assertEquals("dependent_retained",done.getAsJsonObject("cleanup").getAsJsonObject("Parent").get("outcome").getAsString());assertEquals(3,b.submits);}}
    @Test public void fakeTerminalCleanupCacheWithoutLedgerProofIsRejected()throws Exception{try(var f=new TestDataLedgerTest.Fixture()){Backend b=new Backend();Path root=f.path.resolve("sets");var service=new TestDataSetService(root,f.ledger,b);String id=service.prepare(f.id,TARGET,"one",HOST,plan(),true).get("set_id").getAsString();for(int i=0;i<5;i++)service.status(id,f.id,TARGET);Path file=root.resolve(id+".json");JsonObject doc=JsonParser.parseString(Files.readString(file)).getAsJsonObject();doc.addProperty("phase","cleanup");doc.addProperty("state","completed");JsonObject fake=new JsonObject();fake.addProperty("state","completed");fake.addProperty("outcome","marked_for_deletion");doc.getAsJsonObject("cleanup").add("Child",fake);Files.writeString(file,doc.toString());assertThrows(IllegalArgumentException.class,()->service.status(id,f.id,TARGET));assertEquals(2,b.submits);}}
}
